            <text x={190} y={300} fill={C.accentText} fontSize={10}>actual orbit</text>
            <line x1={170} y1={308} x2={186} y2={308} stroke="#3b4060" strokeWidth={1.5} strokeDasharray="2 2" />
            <text x={190} y={312} fill={C.textMuted} fontSize={10}>circular ref</text>
          </>
        )}
      </svg>

      {/* Controls */}
      <div style={{ display: "flex", gap: 10 }}>
        {["▶ Play", "⏸ Pause", "↺ Reset"].map((label, i) => (
          <button
            key={i}
            onClick={[startAnim, stopAnim, resetAnim][i]}
            style={{
              background: i === 0 ? C.accentSoft : C.surface,
              color: i === 0 ? C.accentText : C.textSecondary,
              border: `1px solid ${i === 0 ? C.accent : C.divider}`,
              borderRadius: 8,
              padding: "6px 16px",
              fontSize: 12,
              cursor: "pointer",
              fontWeight: 600,
            }}
          >
            {label}
          </button>
        ))}
      </div>
    </div>
  );
}

