// ══════════════════════════════════════════════════════
// ENERGY CARD
// ══════════════════════════════════════════════════════
function EnergyCard() {
  const [vFactor, setVFactor] = useState(1.0);
  const G = 6.674e-11, M = 2e30, m = 6e24, r = 1.5e11;
  const vc = Math.sqrt(G * M / r);
  const v = vc * vFactor;
  const KE = 0.5 * m * v * v;
  const PE = -G * M * m / r;
  const E = KE + PE;
  const KEn = KE / Math.abs(PE);
  const En = E / Math.abs(PE);

  const barW = (val, max) => `${Math.min(100, Math.abs(val / max) * 100).toFixed(1)}%`;

  return (
    <Card accent={C.teal}>
      <SectionLabel icon="⚡" text="Energy Budget" color={C.teal} />
      <div style={{ fontSize: 12, color: C.textSecondary, marginBottom: 16 }}>
        Adjust velocity to see how kinetic and potential energy shift.
      </div>

      <input
        type="range" min={0.3} max={1.0} step={0.01}
        value={vFactor}
        onChange={(e) => setVFactor(parseFloat(e.target.value))}
        style={{ width: "100%", accentColor: C.teal, marginBottom: 18 }}
      />
      <div style={{ fontSize: 12, color: C.textSecondary, marginBottom: 18, textAlign: "center" }}>
        <KT tex={`v = ${vFactor.toFixed(2)}\\, v_c`} />
      </div>

      {[
        { label: "Kinetic Energy (KE)", val: KEn, color: C.teal, tex: "\\frac{1}{2}mv^2" },
        { label: "Potential Energy (PE)", val: -1, color: C.red, tex: "-\\frac{GMm}{r}" },
        { label: "Total Energy (E)", val: En, color: En < 0 ? C.green : C.amber, tex: "E = KE + PE" },
      ].map((row, i) => (
        <div key={i} style={{ marginBottom: 14 }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 5 }}>
            <span style={{ fontSize: 12, color: C.textSecondary }}>{row.label}</span>
            <span style={{ fontSize: 12, color: row.color, fontWeight: 700 }}>
              <KT tex={`${row.val.toFixed(3)}\\,|PE_0|`} />
            </span>
          </div>
          <div style={{ background: C.bg, borderRadius: 6, height: 10, overflow: "hidden" }}>
            <div
              style={{
                width: barW(row.val, 1),
                height: "100%",
                background: row.color,
                borderRadius: 6,
                transition: "width 0.2s",
                opacity: 0.8,
              }}
            />
          </div>
        </div>
      ))}

      <div
        style={{
          marginTop: 10,
          padding: "10px 14px",
          background: En < 0 ? C.greenSoft : C.amberSoft,
          border: `1px solid ${En < 0 ? C.green : C.amber}`,
          borderRadius: 8,
          fontSize: 12,
          color: En < 0 ? C.green : C.amber,
          fontWeight: 600,
        }}
      >
        {En < 0
          ? "✓ E < 0 — Bound orbit (planet stays captured)"
          : "⚠ E ≥ 0 — Unbound — planet escapes"}
      </div>
    </Card>
  );
}

